INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(34011, 'Revelation 3:10', 'Revelation', 3, 10, 'په دې خاطر چې تاسو په صبر او زغم سره زما په کلام باندې عمل کړی دی، نو زه به هم تاسو د ازمېښت د هغه ساعت نه وساتم چې د نړۍ په ټولو خلکو باندې به راځي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation3_verse_10.mp3', '', 1761754199, 1761754199),
(34012, 'Revelation 3:11', 'Revelation', 3, 11, 'زه زر راځم. نو څه چې درسره دي هغه ټینګ وساتئ، ترڅو هېڅوک ونه شي کولای ستاسو تاج واخلي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation3_verse_11.mp3', '', 1761754199, 1761754199),
(34013, 'Revelation 3:12', 'Revelation', 3, 12, 'څوک چې بریالی شي، نو زه به د هغه نه د خپل خدای د کور ستنه جوړه کړم او هغه به هېڅکله د هغه ځای څخه دباندې ونه وځي. زه به په هغه باندې د خپل خدای نوم ولیکم او د خپل خدای د ښار یعنې نوي اورشلیم نوم چې د اسمان نه د خدای له خوا راښکته کیږي، ولیکم او همدارنګه خپل نوی نوم به په هغه باندې ولیکم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation3_verse_12.mp3', '', 1761754199, 1761754199),
(34014, 'Revelation 3:13', 'Revelation', 3, 13, 'څوک چې غوږونه لري، نو څه چې روح القدس کلیساګانو ته وایي، هغو خبرو ته دې غوږ ونیسي!» د لایودیکیې کلیسا ته د عیسی مسیح پیغام', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation3_verse_13.mp3', '', 1761754199, 1761754199),
(34015, 'Revelation 3:14', 'Revelation', 3, 14, 'د لایودیکیې د کلیسا فرښتې ته ولیکه: «دا د هغه چا خبرې دي چې امین دی، هغه وفادار او رښتینی شاهد دی او د خدای د پیدایښت پیل دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation3_verse_14.mp3', '', 1761754199, 1761754199),
(34016, 'Revelation 3:15', 'Revelation', 3, 15, 'ستاسو کلیسا چې کوم کارونه کړي دي زه د هغو ټولو نه خبر یم. زه پوهېږم چې تاسو نه ساړه یئ او نه تاوده، بلکې نیمګړي یئ. کاشکې چې تاسو تاوده یا ساړه وای،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation3_verse_15.mp3', '', 1761754199, 1761754199),
(34017, 'Revelation 3:16', 'Revelation', 3, 16, 'خو دا چې تاسو نه تاوده یئ او نه ساړه، بلکې نیمګړي یئ. نو زه به تاسو د خپلې خولې نه دباندې وغورځوم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation3_verse_16.mp3', '', 1761754199, 1761754199),
(34018, 'Revelation 3:17', 'Revelation', 3, 17, 'ځکه تاسو وایئ: ‹مونږ شتمن یو، مونږ هرڅه لرو او هېڅ شي ته اړتیا نه لرو،› خو تاسو نه پوهېږئ چې تاسو بدبخته، بېچاره، غریب، ړانده او لوڅ یئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation3_verse_17.mp3', '', 1761754199, 1761754199),
(34019, 'Revelation 3:18', 'Revelation', 3, 18, 'زه تا ته مشوره درکوم چې زما څخه داسې سره زر واخله چې په اور کې پاک شوي دي چې شتمن شې، سپین کالي راڅخه واخله چې ته یې واغوندې چې د لوڅوالي شرم دې پټ شي او د سترګو ملهم راڅخه واخله چې په لګولو سره یې ستا سترګې بینا شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation3_verse_18.mp3', '', 1761754199, 1761754199),
(34020, 'Revelation 3:19', 'Revelation', 3, 19, 'زه هغه څوک رټم او اصلاح کوم چې په ما ګران وي، نو غیرتمند اوسئ او توبه وباسئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation3_verse_19.mp3', '', 1761754199, 1761754199),
(34021, 'Revelation 3:20', 'Revelation', 3, 20, 'ګورئ، زه په دروازه کې ولاړ یم او هغه ټکوم. که څوک زما اواز اوري او دروازه خلاصه کړي، نو زه به ورننوځم. زه به د هغه سره او هغه به زما سره ډوډۍ وخوري.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation3_verse_20.mp3', '', 1761754199, 1761754199),
(34022, 'Revelation 3:21', 'Revelation', 3, 21, 'څوک چې بریالی شي، نو زه به ورته دا حق ورکړم چې زما سره زما په تخت باندې کښېني، لکه څنګه چې زه بریالی شوم او د خپل پلار سره په تخت باندې کښېناستم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation3_verse_21.mp3', '', 1761754199, 1761754199),
(34023, 'Revelation 3:22', 'Revelation', 3, 22, 'څوک چې غوږونه لري، نو څه چې روح القدس کلیساګانو ته وایي، هغو خبرو ته دې غوږ ونیسي!»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation3_verse_22.mp3', '', 1761754199, 1761754199),
(34024, 'Ephesians 6:1', 'Ephesians', 6, 1, 'ای اولادونو، د څښتن د پیروانو په توګه د خپل مور او پلار منونکي اوسئ، ځکه چې دا سم کار دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/ephesians6_verse_1.mp3', '', 1761754199, 1761754199),
(34025, 'Ephesians 6:2', 'Ephesians', 6, 2, 'دا لومړی حکم دی چې په کې وعده شوې ده: «د خپل مور او پلار عزت کوئ.» او د هغه وعده دا وه:', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/ephesians6_verse_2.mp3', '', 1761754199, 1761754199),
(34026, 'Ephesians 6:3', 'Ephesians', 6, 3, '«نو تاسو به نېکمرغه یئ او په دنیا کې به زیات عمر ولرئ.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/ephesians6_verse_3.mp3', '', 1761754199, 1761754199),
(34027, 'Ephesians 6:4', 'Ephesians', 6, 4, 'ای پلرونو، تاسو د خپلو اولادونو سره داسې چلند مه کوئ چې هغوی په قهر شي، بلکې د څښتن په طریقه هغوی اصلاح کړئ او روزنه یې وکړئ. د بادارانو او غلامانو ترمنځ اړیکې', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/ephesians6_verse_4.mp3', '', 1761754199, 1761754199),
(34028, 'Ephesians 6:5', 'Ephesians', 6, 5, 'ای غلامانو، په داسې وېره او لړزېدلو سره د زړه د اخلاصه د خپلو دنیاوي بادارانو تابعداري کوئ، لکه څنګه چې د مسیح تابعداري کوئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/ephesians6_verse_5.mp3', '', 1761754199, 1761754199),
(34029, 'Ephesians 6:6', 'Ephesians', 6, 6, 'دا تابعداري یوازې د دې دپاره مه کوئ چې کله هغوی تاسو څاري او تاسو هغوی خوشحاله کوئ، بلکې د مسیح د غلامانو په توګه د زړه له کومي د خدای رضا پوره کوئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/ephesians6_verse_6.mp3', '', 1761754199, 1761754199),
(34030, 'Ephesians 6:7', 'Ephesians', 6, 7, 'په شوق سره خدمت کوئ، داسې لکه چې د څښتن خدمت کوئ، نه د انسان.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/ephesians6_verse_7.mp3', '', 1761754199, 1761754199),
(34031, 'Ephesians 6:8', 'Ephesians', 6, 8, 'ځکه تاسو پوهېږئ چې څښتن هر یو ته د ښو کارونو له مخې اجر ورکوي، که هغه غلام وي یا ازاد.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/ephesians6_verse_8.mp3', '', 1761754199, 1761754199),
(34032, 'Ephesians 6:9', 'Ephesians', 6, 9, 'ای بادارانو، تاسو هم د خپلو غلامانو سره همداسې چلند کوئ. ګواښونه پرېږدئ. یاد ساتئ چې تاسو دواړه په اسمان کې یو بادار لرئ او هغه د هېچا طرفداري نه کوي. د خدای کاملې زغرې واغوندئ', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/ephesians6_verse_9.mp3', '', 1761754199, 1761754199),
(34033, 'Ephesians 6:10', 'Ephesians', 6, 10, 'اخر دا چې په څښتن او د هغه په لوی قدرت کې قوي اوسئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/ephesians6_verse_10.mp3', '', 1761754199, 1761754199),
(34034, 'Ephesians 6:11', 'Ephesians', 6, 11, 'د خدای هغه کاملې زغرې واغوندئ چې تاسو ته یې تیارې کړې دي، ترڅو وکولای شئ د شیطان د دسیسو په وړاندې ټینګ ودرېږئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/ephesians6_verse_11.mp3', '', 1761754199, 1761754199),
(34035, 'Ephesians 6:12', 'Ephesians', 6, 12, 'ځکه چې زمونږ جنګ د انسان سره نه دی، بلکې د حاکمانو، د واک د خاوندانو، د دې تیارې دنیا د واکمنو قدرتونو او په اسماني ځایونو کې د بدو روحاني قوتونو په خلاف دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/ephesians6_verse_12.mp3', '', 1761754199, 1761754199),
(34036, 'Ephesians 6:13', 'Ephesians', 6, 13, 'له همدې امله تاسو د خدای کاملې زغرې واغوندئ، ترڅو وکولای شئ په هغه بده ورځ د دښمن په وړاندې کلک ودرېږئ او د جنګ تر پایه ټینګ پاتې شئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/ephesians6_verse_13.mp3', '', 1761754199, 1761754199),
(34037, 'Ephesians 6:14', 'Ephesians', 6, 14, 'نو بیا ټینګ ودرېږئ او د حقیقت پټۍ د ملا نه وتړئ او د عدالت زغره واغوندئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/ephesians6_verse_14.mp3', '', 1761754199, 1761754199),
(34038, 'Ephesians 6:15', 'Ephesians', 6, 15, 'خپل بوټان د سولې او سلامتۍ د زېري د خپرولو دپاره په پښو کړئ', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/ephesians6_verse_15.mp3', '', 1761754199, 1761754199),
(34039, 'Ephesians 6:16', 'Ephesians', 6, 16, 'او د دې ټولو سره د ایمان سپر راواخلئ، ترڅو د هغه په وسیله وکولای شئ چې د شیطان اور لرونکي غشي تباه کړئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/ephesians6_verse_16.mp3', '', 1761754199, 1761754199),
(34040, 'Ephesians 6:17', 'Ephesians', 6, 17, 'د خلاصون هغه د زغرو خولۍ او د روح القدس توره چې د خدای کلام دی، راواخلئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/ephesians6_verse_17.mp3', '', 1761754199, 1761754199),
(34041, 'Ephesians 6:18', 'Ephesians', 6, 18, 'هر وخت د روح القدس په لارښوونه دعا او زارۍ کوئ. د همدې دپاره بېداره اوسئ او تل د خدای د ټولو خلکو دپاره دعا کوئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/ephesians6_verse_18.mp3', '', 1761754199, 1761754199),
(34042, 'Ephesians 6:19', 'Ephesians', 6, 19, 'زما دپاره هم دعا وکړئ چې کله زه خبرې کوم، ماته خدای د وینا توان راکړي او وکولای شم په زړورتیا سره د زېري پټ راز اعلان کړم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/ephesians6_verse_19.mp3', '', 1761754199, 1761754199),
(34043, 'Ephesians 6:20', 'Ephesians', 6, 20, 'ځکه چې د همدې زېري په خاطر په زنځیرونو تړل شوی استازی یم، نو دعا کوئ لکه څنګه چې لازمه ده هغه په زړورتیا سره اعلان کړم. اخرنۍ خبرې', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/ephesians6_verse_20.mp3', '', 1761754199, 1761754199),
(34044, 'Ephesians 6:21', 'Ephesians', 6, 21, 'تیخیکاس چې زمونږ ګران ورور او د څښتن وفادار خدمتګار دی، هغه به تاسو ته هرڅه ووایي، ترڅو تاسو پوه شئ چې زه څنګه یم او څه کوم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/ephesians6_verse_21.mp3', '', 1761754199, 1761754199),
(34045, 'Ephesians 6:22', 'Ephesians', 6, 22, 'ما هغه تاسو ته د دې مقصد دپاره درولېږه چې تاسو زمونږ د حال او احوال نه خبر کړي او ستاسو زړونو ته ډاډګېرنه درکړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/ephesians6_verse_22.mp3', '', 1761754199, 1761754199),
(34046, 'Ephesians 6:23', 'Ephesians', 6, 23, 'پلار خدای او څښتن عیسی مسیح دې ټولو خویندو او ورونو ته سلامتي او د ایمان سره مینه ورکړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/ephesians6_verse_23.mp3', '', 1761754199, 1761754199),
(34047, 'Ephesians 6:24', 'Ephesians', 6, 24, 'د خدای فضل دې وي په هغو ټولو چې زمونږ د څښتن عیسی مسیح سره نه‌ختمېدونکې مینه لري.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/ephesians6_verse_24.mp3', '', 1761754199, 1761754199),
(34048, 'John 7:1', 'John', 7, 1, 'هغې نه وروسته عیسی په جلیل کې ګرځېده. هغه نه غوښتل چې په یهودیه کې پاتې شي، ځکه چې د یهودیانو مشرانو غوښتل هغه ووژني.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john7_verse_1.mp3', '', 1761754199, 1761754199),
(34049, 'John 7:2', 'John', 7, 2, 'کله چې د یهودیانو د جونګړو اختر رانژدې شو،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john7_verse_2.mp3', '', 1761754199, 1761754199),
(34050, 'John 7:3', 'John', 7, 3, 'نو ورونو یې عیسی ته وویل: «دا سیمه پرېږده او یهودیې ته لاړ شه، ترڅو ستا پیروان ستا معجزې وویني.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john7_verse_3.mp3', '', 1761754199, 1761754199),
(34051, 'John 7:4', 'John', 7, 4, 'څوک چې غواړي مشهور شي، نو هغه خپل کارونه په پټه نه کوي. که چېرې ته داسې کارونه کوې نو پرېږده چې ټوله نړۍ دې وپېژني.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john7_verse_4.mp3', '', 1761754199, 1761754199),
(34052, 'John 7:5', 'John', 7, 5, 'ځکه چې د هغه ورونو هم په هغه باندې ایمان نه درلود.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john7_verse_5.mp3', '', 1761754199, 1761754199),
(34053, 'John 7:6', 'John', 7, 6, 'عیسی هغوی ته وویل: «زما دپاره ټاکل شوی وخت لا تر‌اوسه نه دی رارسېدلی، خو ستاسو دپاره هر وخت مناسب دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john7_verse_6.mp3', '', 1761754199, 1761754199),
(34054, 'John 7:7', 'John', 7, 7, 'د نړۍ خلک نه شي کولای کوم دلیل پیدا کړي چې ستاسو نه کرکه وکړي، خو زما نه کرکه کوي ځکه چې زه هغوی ته شاهدي ورکوم چې د دوی کارونه غلط دي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john7_verse_7.mp3', '', 1761754199, 1761754199),
(34055, 'John 7:8', 'John', 7, 8, 'تاسو د اختر دپاره لاړ شئ، زه دې اختر ته نه ځم ځکه چې زما دپاره هغه ټاکل شوی وخت لا نه دی رارسېدلی.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john7_verse_8.mp3', '', 1761754199, 1761754199),
(34056, 'John 7:9', 'John', 7, 9, 'هغه دا خبره وکړه او په جلیل کې پاتې شو. عیسی د جونګړو اختر ته ځي', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john7_verse_9.mp3', '', 1761754199, 1761754199),
(34057, 'John 7:10', 'John', 7, 10, 'وروسته له هغې چې د عیسی ورونه اختر ته لاړل، نو عیسی هم لاړ خو په ښکاره نه بلکې په پټه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john7_verse_10.mp3', '', 1761754199, 1761754199),
(34058, 'John 7:11', 'John', 7, 11, 'د یهودیانو مشران د اختر په ورځو کې هغه پسې ګرځېدل او د خلکو نه یې پوښتنه کوله: «هغه سړی چېرته دی؟»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john7_verse_11.mp3', '', 1761754199, 1761754199),
